solution:
let numbers = []

while true {
  let line = ask()
  if line == nothing or line == "done" {
    stop
  }
  try {
    push(numbers, num(line))
  } catch e {
    say "Skipping: {line}"
  }
}

if len(numbers) == 0 {
  say "No numbers entered."
} else {
  say "Count: {len(numbers)}"
  say "Total: {sum(numbers)}"
  say "Average: {round(sum(numbers) / len(numbers), 2)}"
  say "Largest: {max(numbers)}"
}
